// GOOD: Cache references, use events
public class EnemyManager : MonoBehaviour
{
    public List<Enemy> enemies = new List<Enemy>();

    public void RegisterEnemy(Enemy e) => enemies.Add(e);
    public void UnregisterEnemy(Enemy e) => enemies.Remove(e);

    void Update()
    {
        // Use cached list
        foreach (var enemy in enemies) { /* check distance */ }
    }
}

// BAD: LINQ creates garbage (foreach with LINQ = GC allocation)
void FindNearestEnemy()
{
    var nearest = enemies.OrderBy(e => Vector3.Distance(transform.position, e.transform.position)).First();
}

// GOOD: Manual loop, no allocation
Enemy FindNearestEnemy()
{
    float minDist = float.MaxValue;
    Enemy nearest = null;
    foreach (var enemy in enemies)
    {
        float dist = Vector3.Distance(transform.position, enemy.transform.position);
        if (dist < minDist) { minDist = dist; nearest = enemy; }
    }
    return nearest;
}

// ===== UNITY: Static Batching =====
/*
Static batching combines static (non-moving) objects that share the same material
into a single mesh, drastically reducing draw calls.

How to enable:
1. Tag objects as "Batching Static" in the Inspector
2. Edit -> Project Settings -> Player -> "Static Batching" checkbox
*/

// ===== GPU Instancing (draw many copies in one call) =====
using UnityEngine;

public class InstancedRendering : MonoBehaviour
{
    public Mesh instanceMesh;
    public Material instanceMaterial;
    public int instanceCount = 100000;

    void Start()
    {
        // Enable GPU instancing on the material
        instanceMaterial.enableInstancing = true;

        // Generate random transforms
        Matrix4x4[] matrices = new Matrix4x4[instanceCount];
        Vector4[] colors = new Vector4[instanceCount];

        for (int i = 0; i < instanceCount; i++)
        {
            Vector3 position = new Vector3(
                Random.Range(-50f, 50f),
                Random.Range(-50f, 50f),
                Random.Range(-50f, 50f)
            );
            Quaternion rotation = Random.rotation;
            Vector3 scale = Vector3.one * Random.Range(0.5f, 2f);

            matrices[i] = Matrix4x4.TRS(position, rotation, scale);
            colors[i] = Random.ColorHSV();
        }

        // Draw all instances in ONE draw call (instead of 100000!)
        // This runs in OnRenderObject or similar
        Graphics.DrawMeshInstanced(
            instanceMesh,
            0,
            instanceMaterial,
            matrices,
            instanceCount
        );
    }

    // Alternative: Unity's built-in SRP Batcher
    // Works automatically when using SRP (URP/HDRP) and ShaderGraph materials
    // Reduces draw calls by batching across different meshes with same shader
}

