// ===== MOD PLUGIN SYSTEM =====
// A simple plugin system that lets mods extend the game

// Plugin.h - Core plugin interface
#pragma once
#include <string>
#include <vector>

class IGamePlugin
{
public:
    virtual ~IGamePlugin() = default;
    virtual std::string GetName() const = 0;
    virtual std::string GetVersion() const = 0;
    virtual bool OnLoad() = 0;         // Called when plugin is loaded
    virtual void OnUnload() = 0;        // Called when plugin is unloaded
    virtual void OnUpdate(float dt) = 0; // Called every frame
    virtual void OnRender() = 0;        // Called every render frame
};

// PluginManager.cpp - Loads and manages plugins
#include "PluginManager.h"
#include <iostream>
#include <filesystem>
#ifdef _WIN32
#include <windows.h>
#endif

class PluginManager
{
    std::vector<IGamePlugin*> plugins;
    std::vector<void*> handles;

public:
    bool LoadPlugins(const std::string& directory)
    {
        for (const auto& entry : std::filesystem::directory_iterator(directory))
        {
            if (entry.path().extension() == ".dll" || entry.path().extension() == ".so")
            {
                LoadPlugin(entry.path().string());
            }
        }
        return true;
    }

    bool LoadPlugin(const std::string& path)
    {
#ifdef _WIN32
        HMODULE handle = LoadLibraryA(path.c_str());
        if (!handle)
        {
            std::cerr << "Failed to load plugin: " << path << std::endl;
            return false;
        }

        using CreatePluginFunc = IGamePlugin*(*)();
        CreatePluginFunc createFunc = (CreatePluginFunc)GetProcAddress(handle, "CreatePlugin");

        if (!createFunc)
        {
            FreeLibrary(handle);
            return false;
        }

        IGamePlugin* plugin = createFunc();
        if (plugin && plugin->OnLoad())
        {
            plugins.push_back(plugin);
            handles.push_back(handle);
            std::cout << "Loaded plugin: " << plugin->GetName() << " v" << plugin->GetVersion() << std::endl;
            return true;
        }
#endif
        return false;
    }

    void UpdateAll(float dt)
    {
        for (auto* plugin : plugins)
            plugin->OnUpdate(dt);
    }
};

